-- Corrected Iris capability graph.
-- Existing implementations are upgraded into a governed dependency hierarchy;
-- this migration never lowers the semantic requirements of the corrected architecture.

on conflict (capability_id,version) do update set operator_id=excluded.operator_id,operator_version=excluded.operator_version,evidence_requirements=excluded.evidence_requirements,dependencies=excluded.dependencies,validation_rules=excluded.validation_rules,output_type=excluded.output_type,recursive=excluded.recursive,cross_domain=excluded.cross_domain,active=true;

values ('iris.full_intelligence','1.0.0','computeFullIntelligence','1',jsonb_build_array('authorized_plaid_evidence','canonical_financial_model'),jsonb_build_array('analysis','pattern','relationship','anomaly','causal','predictive','scenario','decision','recommendation','outcome','learning','emergent'),jsonb_build_array('user_isolation','lineage_present','evidence_state_valid','dependency_results_valid'),'full_intelligence_snapshot',true,true,true)
on conflict (capability_id,version) do update set dependencies=excluded.dependencies,validation_rules=excluded.validation_rules,active=true;
